def connected_components(grid, connectivity=8):
    """Find connected components in a grid"""
    if not grid:
        return []
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if not visited[r][c]:
                # Start BFS/DFS
